-- Role-specific erasure journal; a retained anonymous app_users tombstone preserves shared ownership and legal FKs.
CREATE TABLE app_account_erasure(user_id TEXT PRIMARY KEY REFERENCES app_users(id),transfer_actor TEXT UNIQUE,cursor INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN('RUNNING','REVIEW_REQUIRED')),requested_at INTEGER NOT NULL,updated_at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TRIGGER app_erasure_app_credentials_insert BEFORE INSERT ON "app_credentials" WHEN EXISTS(SELECT 1 FROM app_account_erasure WHERE user_id=NEW."user_id") BEGIN SELECT RAISE(ABORT,'Account erasure in progress'); END;
