CREATE TRIGGER app_erasure_user_update BEFORE UPDATE ON app_users WHEN EXISTS(SELECT 1 FROM app_account_erasure WHERE user_id=OLD.id) AND (NEW.status<>'DELETED' OR NEW.primary_email IS NOT NULL OR NEW.display_name IS NOT NULL OR NEW.first_name IS NOT NULL OR NEW.last_name IS NOT NULL OR NEW.avatar_url IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Erased account cannot be reactivated'); END;
